/** How far ahead the overdue job looks when collecting due issues. */
export const OVERDUE_LOOKAHEAD_HOURS: number = 24;

/**
 * Deepest level a sub-issue may occupy. A root issue is level 0, so a chain
 * may contain at most this many parent links.
 */
export const MAX_SUB_ISSUE_DEPTH: number = 3;

/**
 * Parent/child placement rules for issues.
 *
 * A root sits at level 0. Nothing may sit deeper than `MAX_SUB_ISSUE_DEPTH`,
 * and a move is judged by where the issue's deepest descendant would land,
 * because the issues below it keep their parent links and move with it.
 */
import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";
import { CLOSED_ISSUE_STATUSES, type IssueStatus } from "@/types/issue";
import type { IssueRollup } from "@/types/issue";

export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: "cycle" | "too_deep",
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or one of its sub-issues.`
        : `Issue ${issueId} would exceed the maximum sub-issue depth.`,
    );
    this.name = "IssueHierarchyError";
  }
}

export interface IssueTreeNode {
  readonly id: string;
  readonly parentId: string | null;
  readonly status: IssueStatus;
  readonly archived: boolean;
}

export function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

export function issueTreeNodes(
  issues: readonly {
    readonly id: string;
    readonly parentId: string | null;
    readonly status: IssueStatus;
    readonly archivedAt: string | null;
  }[],
): readonly IssueTreeNode[] {
  return issues.map((issue) => ({
    id: issue.id,
    parentId: issue.parentId,
    status: issue.status,
    archived: issue.archivedAt !== null,
  }));
}

/** Rejects a parent that would loop the tree or push a descendant past the depth cap. */
export function assertIssuePlacement(
  issueId: string,
  parentId: string | null,
  nodes: readonly IssueTreeNode[],
): void {
  const parents = parentMap(nodes);
  if (parentId !== null && (parentId === issueId || reaches(parentId, issueId, parents))) {
    throw new IssueHierarchyError(issueId, "cycle");
  }

  const base = parentId === null ? 0 : levelOf(parentId, parents, issueId) + 1;
  const deepest = base + subtreeDepth(issueId, nodes);
  if (deepest > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issueId, "too_deep");
  }
}

/** A brand-new issue has no descendants; only the parent's level matters. */
export function assertNewSubIssueDepth(
  parentId: string,
  nodes: readonly IssueTreeNode[],
): void {
  const nextLevel = levelOf(parentId, parentMap(nodes), parentId) + 1;
  if (nextLevel > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(parentId, "too_deep");
  }
}

/** Every issue below `rootId`, nearest first. Archived rows are included. */
export function collectDescendantIds(
  rootId: string,
  nodes: readonly { readonly id: string; readonly parentId: string | null }[],
): readonly string[] {
  const children = childMap(nodes);
  const result: string[] = [];
  const seen = new Set<string>([rootId]);
  const queue = [...(children.get(rootId) ?? [])];

  while (queue.length > 0) {
    const id = queue.shift();
    if (id === undefined || seen.has(id)) continue;
    seen.add(id);
    result.push(id);
    for (const child of children.get(id) ?? []) queue.push(child);
  }

  return result;
}

/**
 * Counts of non-archived issues below `rootId` at any depth.
 * Closed means done or canceled; archived rows are skipped but still traversed.
 */
export function summarizeDescendants(
  rootId: string,
  nodes: readonly IssueTreeNode[],
): IssueRollup {
  const children = childMap(nodes);
  const byId = new Map(nodes.map((node) => [node.id, node]));
  const seen = new Set<string>([rootId]);
  const queue = [...(children.get(rootId) ?? [])];
  let total = 0;
  let open = 0;
  let closed = 0;

  while (queue.length > 0) {
    const id = queue.shift();
    if (id === undefined || seen.has(id)) continue;
    seen.add(id);
    const node = byId.get(id);
    if (node && !node.archived) {
      total += 1;
      if (isClosedStatus(node.status)) closed += 1;
      else open += 1;
    }
    for (const child of children.get(id) ?? []) queue.push(child);
  }

  return { total, open, closed };
}

function parentMap(
  nodes: readonly { readonly id: string; readonly parentId: string | null }[],
): Map<string, string | null> {
  return new Map(nodes.map((node) => [node.id, node.parentId]));
}

function childMap(
  nodes: readonly { readonly id: string; readonly parentId: string | null }[],
): Map<string, string[]> {
  const children = new Map<string, string[]>();
  for (const node of nodes) {
    if (node.parentId === null) continue;
    const list = children.get(node.parentId);
    if (list) list.push(node.id);
    else children.set(node.parentId, [node.id]);
  }
  return children;
}

/** True when walking parents from `start` reaches `target`. */
function reaches(
  start: string,
  target: string,
  parents: ReadonlyMap<string, string | null>,
): boolean {
  const seen = new Set<string>();
  let current: string | null = start;
  while (current !== null) {
    if (current === target) return true;
    if (seen.has(current)) return false;
    seen.add(current);
    const parent = parents.get(current);
    if (parent === undefined) return false;
    current = parent;
  }
  return false;
}

/** Number of parent links between `id` and its root. A root is 0. */
function levelOf(
  id: string,
  parents: ReadonlyMap<string, string | null>,
  issueId: string,
): number {
  let level = 0;
  const seen = new Set<string>();
  let current = id;
  while (true) {
    if (seen.has(current)) throw new IssueHierarchyError(issueId, "cycle");
    seen.add(current);
    const parent = parents.get(current);
    if (parent === undefined || parent === null) return level;
    level += 1;
    current = parent;
  }
}

/** Longest chain of descendants below `id`. An issue with no children is 0. */
function subtreeDepth(id: string, nodes: readonly IssueTreeNode[]): number {
  const children = childMap(nodes);
  let max = 0;
  const seen = new Set<string>([id]);
  const stack = (children.get(id) ?? []).map((child) => ({ id: child, depth: 1 }));

  while (stack.length > 0) {
    const next = stack.pop();
    if (next === undefined || seen.has(next.id)) continue;
    seen.add(next.id);
    if (next.depth > max) max = next.depth;
    for (const child of children.get(next.id) ?? []) {
      stack.push({ id: child, depth: next.depth + 1 });
    }
  }

  return max;
}

