/** Every issue in the project, archived included, oldest first. Used to walk the tree. */
export async function listProjectIssues(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .orderBy(asc(issues.createdAt), asc(issues.number))
    .all();

  return rows.map((row) => toIssue(row));
}

/** Direct live children of `parentId`, oldest first (creation time, then number). */
export async function listDirectSubIssues(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        eq(issues.projectId, projectId),
        eq(issues.parentId, parentId),
        isNull(issues.archivedAt),
      ),
    )
    .orderBy(asc(issues.createdAt), asc(issues.number))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );

  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

export async function updateIssueParent(
  orgId: OrgId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ parentId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

/**
 * Archives every still-live id in `issueIds`. Rows that are already archived
 * are left untouched, including their `archived_at`. Returned in input order.
 */
export async function archiveLiveIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly Issue[]> {
  if (issueIds.length === 0) return [];

  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        inArray(issues.id, [...issueIds]),
        isNull(issues.archivedAt),
      ),
    )
    .returning()
    .all();

  const byId = new Map(rows.map((row) => [row.id, row]));
  return issueIds.flatMap((id) => {
    const row = byId.get(id);
    return row ? [toIssue(row)] : [];
  });
}

/** Live, still-open issues whose due date has passed. Drives the overdue job. */

