/**
 * Places `issueId` under `parentId`, or makes it a root when `parentId` is
 * null. Sub-issues keep their parent links, so they move with it. A refused
 * placement writes nothing and announces nothing.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  if (input.parentId === issue.parentId) return issue;

  if (input.parentId !== null) {
    await requireLiveSameProjectParent(
      input.orgId,
      issue.projectId,
      input.parentId,
    );
  }

  const projectIssues = await issueRepo.listProjectIssues(
    input.orgId,
    issue.projectId,
  );
  assertIssuePlacement(
    issue.id,
    input.parentId,
    issueTreeNodes(projectIssues),
  );

  const after = await issueRepo.updateIssueParent(
    input.orgId,
    input.issueId,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

/** Direct live sub-issues, oldest first. */
export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return issueRepo.listDirectSubIssues(orgId, issue.projectId, issue.id);
}

/** Counts of every non-archived issue below `issueId`, at any depth. */
export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const projectIssues = await issueRepo.listProjectIssues(orgId, issue.projectId);
  return summarizeDescendants(issue.id, issueTreeNodes(projectIssues));
}

/**
 * The parent of a new issue must be a live issue of the same project.
 * A refusal happens before a number is allocated, so nothing is created
 * and `issue.created` is not announced.
 */
async function assertCreatableParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<void> {
  await requireLiveSameProjectParent(orgId, projectId, parentId);
  const projectIssues = await issueRepo.listProjectIssues(orgId, projectId);
  assertNewSubIssueDepth(parentId, issueTreeNodes(projectIssues));
}

/** Missing, other-project and other-workspace parents are all not-found. */
async function requireLiveSameProjectParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (!parent || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

