  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    await notify(payload.orgId, "member_joined", [org.ownerId], {
      title: "A new member joined",
      body: `${payload.userId} joined as ${payload.role}`,
      href: "/settings/members",
      actorId: payload.userId,
    });
  });

  subscribe("issue.status_changed", async (payload) => {
    const closing = !isClosedStatus(payload.from) && isClosedStatus(payload.to);
    if (!closing) return;
    await maybeNotifySubIssuesCompleted(
      payload.orgId,
      payload.issueId,
      payload.actorId,
    );
  });

  subscribe("issue.archived", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue || isClosedStatus(issue.status)) return;
    await maybeNotifySubIssuesCompleted(
      payload.orgId,
      payload.issueId,
      payload.actorId,
    );
  });
}

/**
 * Tells the direct parent's assignee when a sub-issue stops being open and
 * nothing open remains below that parent. Preferences and the actor exclusion
 * are applied by `notify`. Re-closing after a reopen tells them again.
 */
async function maybeNotifySubIssuesCompleted(
  orgId: OrgId,
  issueId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue?.parentId) return;

  const parent = await issueRepo.findIssueById(orgId, issue.parentId);
  if (!parent || parent.archivedAt !== null || parent.assigneeId === null) return;

  const projectIssues = await issueRepo.listProjectIssues(orgId, parent.projectId);
  const nodes = issueTreeNodes(projectIssues);
  if (collectDescendantIds(parent.id, nodes).length === 0) return;
  if (summarizeDescendants(parent.id, nodes).open > 0) return;

  await notify(orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "Sub-issues completed",
    body: `Every sub-issue under ${parent.title} is finished`,
    href: `/issues/${parent.id}`,
    actorId,
  });
}

