import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { subscribe } from "@/lib/event-bus";
import { IssueHierarchyError } from "@/lib/issue-hierarchy";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { NotFoundError } from "@/server/services/_support";
import * as issueService from "@/server/services/issue-service";
import { listNotifications } from "@/server/services/notification-service";
import type { IssueId, ProjectId } from "@/types/common";
import type { Issue } from "@/types/issue";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("hier");
  other = await createTenant("hierother");
});

afterAll(() => cleanup());

function input(title: string, parentId: IssueId | null = null, projectId?: ProjectId) {
  return {
    ...issueInput(tenant.org.id, projectId ?? tenant.project.id, { title }),
    parentId,
  };
}

async function notices(recipient: typeof tenant.userIds.admin) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId: recipient,
    unreadOnly: false,
    kind: ["sub_issues_completed"],
    limit: 50,
    cursor: null,
  });
  return page.items;
}

describe("sub-issues", () => {
  it("places, lists, rolls up, moves with descendants, and refuses bad parents", async () => {
    const root = await issueService.createIssue(tenant.actors.member, input("Root"));
    const child = await issueService.createIssue(
      tenant.actors.member,
      input("Child", root.id),
    );
    const grand = await issueService.createIssue(
      tenant.actors.member,
      input("Grand", child.id),
    );
    const great = await issueService.createIssue(
      tenant.actors.member,
      input("Great", grand.id),
    );

    expect(great.parentId).toBe(grand.id);

    const created: unknown[] = [];
    const off = subscribe("issue.created", (payload) => {
      created.push(payload);
    });
    await expect(
      issueService.createIssue(tenant.actors.member, input("Too deep", great.id)),
    ).rejects.toMatchObject({ reason: "too_deep", code: "conflict" });
    expect(created).toHaveLength(0);
    off();

    const beforeCount = await issueRepo.countIssues(tenant.org.id, tenant.project.id, {
      includeArchived: true,
    });
    await expect(
      issueService.createIssue(
        tenant.actors.member,
        input("Missing", "01HZZZMISSINGISSUEID0000" as IssueId),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
    const afterCount = await issueRepo.countIssues(tenant.org.id, tenant.project.id, {
      includeArchived: true,
    });
    expect(afterCount).toBe(beforeCount);

    const otherProject = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Other",
      slug: "other-hier",
      key: "OTH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#000000",
      targetDate: null,
    });
    const foreign = await issueService.createIssue(
      tenant.actors.member,
      input("Foreign", null, otherProject.id),
    );
    await expect(
      issueService.createIssue(tenant.actors.member, input("Cross", foreign.id)),
    ).rejects.toBeInstanceOf(NotFoundError);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, foreign.id);
    await expect(
      issueService.createIssue(tenant.actors.member, {
        ...issueInput(tenant.org.id, otherProject.id, { title: "Under archived" }),
        parentId: foreign.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect(
      await issueRepo.countIssues(tenant.org.id, otherProject.id, { includeArchived: true }),
    ).toBe(1);

    const listed = await issueService.listSubIssues(
      tenant.actors.viewer,
      tenant.org.id,
      root.id,
    );
